# R/raster-io.R
# Manual file - NOT generated by orchestrate.R
# Geotransforms, overviews, windowed reads, and the batched dataset summary.

# ============================================================================
# Geotransform
# ============================================================================

#' Get the geotransform of a dataset
#'
#' The six coefficients that map pixel and line to georeferenced coordinates,
#' in GDAL's order: origin x, pixel width, row rotation, origin y, column
#' rotation, pixel height. Note that GDAL's order interleaves the x and y
#' terms, which is not the order the names might suggest.
#'
#' @param x A GDALDataset object
#' @param ... Arguments passed on to methods.
#' @return A named numeric vector of length 6, or NULL when the dataset carries
#'   no geotransform. GDAL reports the identity in that case, which is
#'   indistinguishable from a real identity geotransform, so NULL is used here
#'   instead.
#' @export
#' @examples
#' ds <- gdal_open(system.file("extdata/test.tif", package = "GDAL7"))
#' get_geotransform(ds)
#' gdal_close(ds)
get_geotransform <- S7::new_generic("get_geotransform", "x")

S7::method(get_geotransform, GDALDataset) <- function(x, ...) {
  GDAL7_dataset_get_geotransform(x@.ptr)
}

#' Set the geotransform of a dataset
#'
#' @param x A GDALDataset object, opened for update.
#' @param geotransform A numeric vector of length 6, in GDAL's order.
#' @return `x`, invisibly.
#' @export
set_geotransform <- S7::new_generic(
  "set_geotransform", "x",
  function(x, geotransform) S7::S7_dispatch()
)

S7::method(set_geotransform, GDALDataset) <- function(x, geotransform) {
  GDAL7_dataset_set_geotransform(x@.ptr, as.double(geotransform))
  invisible(x)
}

#' Convert between pixel and georeferenced coordinates
#'
#' `apply_geotransform()` takes pixel and line positions to georeferenced ones.
#' `inv_geotransform()` returns the geotransform that goes the other way, which
#' is what to feed back to `apply_geotransform()` to turn coordinates into
#' pixel positions.
#'
#' Both are vectorised over `pixel` and `line`, so a whole set of positions is
#' one call.
#'
#' @param geotransform A numeric vector of length 6, as [get_geotransform()]
#'   returns.
#' @param pixel,line Numeric vectors of the same length. Fractional positions
#'   are meaningful: whole numbers fall on pixel corners, so the centre of the
#'   first pixel is `pixel = 0.5, line = 0.5`.
#' @return `apply_geotransform()` returns a list of `x` and `y`.
#'   `inv_geotransform()` returns a numeric vector of length 6, or NULL when
#'   the geotransform cannot be inverted.
#' @export
#' @examples
#' ds <- gdal_open(system.file("extdata/test.tif", package = "GDAL7"))
#' gt <- get_geotransform(ds)
#'
#' # The centre of the first pixel, and back again.
#' apply_geotransform(gt, 0.5, 0.5)
#' apply_geotransform(inv_geotransform(gt), -180 + 9, 90 - 9)
#'
#' gdal_close(ds)
apply_geotransform <- function(geotransform, pixel, line) {
  GDAL7_apply_geotransform(
    as.double(geotransform), as.double(pixel), as.double(line)
  )
}

#' @rdname apply_geotransform
#' @export
inv_geotransform <- function(geotransform) {
  GDAL7_inv_geotransform(as.double(geotransform))
}

# ============================================================================
# Overviews
# ============================================================================

#' Number of overviews on a band
#'
#' @param x A GDALRasterBand object
#' @param ... Arguments passed on to methods.
#' @return Integer count.
#' @export
get_overview_count <- S7::new_generic("get_overview_count", "x")

S7::method(get_overview_count, GDALRasterBand) <- function(x, ...) {
  GDAL7_band_get_overview_count(x@.ptr)
}

#' Get one overview of a band
#'
#' @param x A GDALRasterBand object
#' @param index Zero-based overview index, as GDAL numbers them.
#' @return A GDALRasterBand object for the overview, which belongs to the same
#'   dataset as `x`.
#' @export
get_overview <- S7::new_generic(
  "get_overview", "x",
  function(x, index) S7::S7_dispatch()
)

S7::method(get_overview, GDALRasterBand) <- function(x, index) {
  GDALRasterBand(.ptr = GDAL7_band_get_overview(x@.ptr, as.integer(index)))
}

#' Sizes of a band's overviews
#'
#' Which overview level a read will actually touch follows from these sizes and
#' the output size asked for, so this is the cheap way to see what a read at a
#' given size will cost.
#'
#' @param x A GDALRasterBand object
#' @param ... Arguments passed on to methods.
#' @return A data frame of `xsize` and `ysize`, one row per overview, or a
#'   zero-row data frame when the band has none.
#' @export
get_overview_sizes <- S7::new_generic("get_overview_sizes", "x")

S7::method(get_overview_sizes, GDALRasterBand) <- function(x, ...) {
  sizes <- GDAL7_band_get_overview_sizes(x@.ptr)
  data.frame(xsize = sizes$xsize, ysize = sizes$ysize)
}

# ============================================================================
# Windowed reads
# ============================================================================

#' Read a window of raster data
#'
#' Reads a window of a band, or of several bands of a dataset, at a chosen
#' output size. The window and the output size are independent, which is the
#' whole point: asking for a large window at a small output size lets GDAL
#' serve the read from an overview, so a huge raster over `/vsicurl/` costs
#' only the bytes of the overview level it picks.
#'
#' The window is in pixel coordinates and may be fractional. Whole numbers fall
#' on pixel corners, so `c(0, 0, 10, 10)` is the first ten pixels of the first
#' ten rows.
#'
#' Values come back as doubles whatever the band holds, in GDAL's order: the
#' first row of the output first, x varying fastest. That is the transpose of
#' what R's `matrix()` builds from a vector, so reshape with
#' `matrix(values, nrow = out_size[1])` and read the columns as rows, or
#' transpose it.
#'
#' @param x A GDALRasterBand, or a GDALDataset.
#' @param window Numeric of length 4: `c(xoff, yoff, xsize, ysize)` in pixels.
#'   Defaults to the whole raster.
#' @param out_size Integer of length 2: the width and height to return.
#'   Defaults to the size of the window, which is a read with no resampling.
#' @param resample One of "nearest", "bilinear", "cubic", "cubicspline",
#'   "lanczos", "average", "mode", "gauss", "rms".
#' @param bands For a dataset, which bands to read, one-based. Defaults to all
#'   of them. Reading several at once is one pass over the data rather than one
#'   per band.
#' @return For a band, a numeric vector of `out_size[1] * out_size[2]` values.
#'   For a dataset, a named list of one such vector per band.
#' @export
#' @examples
#' ds <- gdal_open(system.file("extdata/test.tif", package = "GDAL7"))
#' band <- get_raster_band(ds, 1)
#'
#' # The whole band.
#' length(read_raster(band))
#'
#' # A 4x4 window, averaged down to 2x2.
#' read_raster(band, window = c(0, 0, 4, 4), out_size = c(2, 2),
#'             resample = "average")
#'
#' # Both bands at once.
#' str(read_raster(ds, out_size = c(5, 5)))
#'
#' gdal_close(ds)
read_raster <- S7::new_generic(
  "read_raster", "x",
  function(x, window = NULL, out_size = NULL, resample = "nearest", bands = NULL) {
    S7::S7_dispatch()
  }
)

S7::method(read_raster, GDALRasterBand) <- function(x, window = NULL,
                                                    out_size = NULL,
                                                    resample = "nearest",
                                                    bands = NULL) {
  if (!is.null(bands)) {
    stop("`bands` applies to a dataset, not to a single band", call. = FALSE)
  }
  window <- resolve_window(window, get_xsize(x), get_ysize(x))
  GDAL7_band_read(x@.ptr, window, resolve_out_size(out_size, window), resample)
}

S7::method(read_raster, GDALDataset) <- function(x, window = NULL,
                                                 out_size = NULL,
                                                 resample = "nearest",
                                                 bands = NULL) {
  if (is.null(bands)) {
    bands <- seq_len(get_raster_count(x))
  }
  window <- resolve_window(window, get_raster_xsize(x), get_raster_ysize(x))
  GDAL7_dataset_read(
    x@.ptr, as.integer(bands), window,
    resolve_out_size(out_size, window), resample
  )
}

resolve_window <- function(window, xsize, ysize) {
  if (is.null(window)) {
    return(c(0, 0, as.double(xsize), as.double(ysize)))
  }
  window <- as.double(window)
  if (length(window) != 4L || anyNA(window)) {
    stop("`window` must be 4 non-missing numbers: xoff, yoff, xsize, ysize",
         call. = FALSE)
  }
  window
}

resolve_out_size <- function(out_size, window) {
  if (is.null(out_size)) {
    return(as.integer(ceiling(window[3:4])))
  }
  out_size <- as.integer(out_size)
  if (length(out_size) != 2L || anyNA(out_size)) {
    stop("`out_size` must be 2 non-missing numbers", call. = FALSE)
  }
  out_size
}

# ============================================================================
# Writing
# ============================================================================

#' Write a raster window
#'
#' The mirror of [read_raster()], with the same window and the same output
#' size, so values read at one size can be written back at another and GDAL
#' resamples between them.
#'
#' Values go in the order they come out: the first row first, x varying
#' fastest, which is the transpose of what `matrix()` builds from a vector.
#'
#' Whatever the band holds, values are given as doubles and GDAL converts. A
#' value the band's type cannot hold is clamped by GDAL rather than wrapped,
#' and it says so.
#'
#' The dataset has to be open for writing: one from [gdal_create()], or one
#' opened with `gdal_open(path, update = TRUE)`. Nothing is guaranteed to be on
#' disk until the dataset is closed with [gdal_close()], or [gdal_flush()] is
#' called.
#'
#' @param x A GDALRasterBand, or a GDALDataset.
#' @param values For a band, a numeric vector. For a dataset, a list of one
#'   numeric vector per band in `bands`.
#' @param window Numeric of length 4: `c(xoff, yoff, xsize, ysize)` in pixels.
#'   Defaults to the whole raster.
#' @param out_size Integer of length 2: the width and height of the block of
#'   values being given. Defaults to the size of the window, which is a write
#'   with no resampling.
#' @param resample How to resample when `out_size` differs from the window.
#'   One of "nearest", "bilinear", "cubic", "cubicspline", "lanczos",
#'   "average", "mode", "gauss", "rms".
#' @param bands For a dataset, which bands to write, one-based. Defaults to
#'   all of them. Writing several at once is one pass over the data.
#' @return `x`, invisibly.
#' @export
#' @examples
#' path <- tempfile(fileext = ".tif")
#' ds <- gdal_create(path, 4, 4, bands = 1, type = "Byte")
#'
#' write_raster(ds, list(as.double(seq_len(16))))
#' read_raster(ds)[[1]]
#'
#' gdal_close(ds)
#' unlink(path)
write_raster <- S7::new_generic(
  "write_raster", "x",
  function(x, values, window = NULL, out_size = NULL, resample = "nearest",
           bands = NULL) {
    S7::S7_dispatch()
  }
)

S7::method(write_raster, GDALRasterBand) <- function(x, values, window = NULL,
                                                     out_size = NULL,
                                                     resample = "nearest",
                                                     bands = NULL) {
  if (!is.null(bands)) {
    stop("`bands` applies to a dataset, not to a single band", call. = FALSE)
  }
  window <- resolve_window(window, get_xsize(x), get_ysize(x))
  GDAL7_band_write(x@.ptr, as.double(values), window,
                   resolve_out_size(out_size, window), resample)
  invisible(x)
}

S7::method(write_raster, GDALDataset) <- function(x, values, window = NULL,
                                                  out_size = NULL,
                                                  resample = "nearest",
                                                  bands = NULL) {
  if (is.null(bands)) {
    bands <- seq_len(get_raster_count(x))
  }
  if (!is.list(values)) {
    stop("For a dataset, `values` is a list of one vector per band",
         call. = FALSE)
  }
  window <- resolve_window(window, get_raster_xsize(x), get_raster_ysize(x))
  GDAL7_dataset_write(
    x@.ptr, lapply(values, as.double), as.integer(bands), window,
    resolve_out_size(out_size, window), resample
  )
  invisible(x)
}

#' Write out everything held in memory
#'
#' A dataset open for writing holds its last blocks in memory until it is
#' closed. This puts them on disk without closing it, which is what makes a
#' file readable by something else while it is still being built.
#'
#' @param x A GDALDataset.
#' @param ... Arguments passed on to methods.
#' @return `x`, invisibly.
#' @export
gdal_flush <- S7::new_generic("gdal_flush", "x")

S7::method(gdal_flush, GDALDataset) <- function(x, ...) {
  GDAL7_dataset_flush(x@.ptr)
  invisible(x)
}

# ============================================================================
# Coordinate reference systems
# ============================================================================

#' Set a dataset's coordinate reference system
#'
#' Anything GDAL understands as a CRS is accepted: `"EPSG:4326"`, a PROJ
#' string, a PROJJSON document, the contents of a `.prj` file, or WKT.
#' [set_projection()] is the same thing for WKT only, which is what GDAL's own
#' `SetProjection` takes.
#'
#' @param x A GDALDataset, open for writing.
#' @param crs A coordinate reference system, in any form GDAL reads.
#' @return `x`, invisibly.
#' @export
#' @examples
#' path <- tempfile(fileext = ".tif")
#' ds <- gdal_create(path, 4, 4)
#' set_crs(ds, "EPSG:3857")
#' substr(get_projection(ds), 1, 30)
#' gdal_close(ds)
#' unlink(path)
set_crs <- S7::new_generic("set_crs", "x", function(x, crs) S7::S7_dispatch())

S7::method(set_crs, GDALDataset) <- function(x, crs) {
  GDAL7_dataset_set_crs(x@.ptr, crs)
  invisible(x)
}

#' A coordinate reference system as WKT
#'
#' The conversion [set_crs()] does, on its own, for checking a CRS string or
#' for seeing what one says.
#'
#' WKT2 is the default because WKT1 cannot carry everything a modern CRS
#' holds: a projection WKT2 names exactly comes back out of WKT1 as
#' `PROJCS["unknown"]`. WKT1 is still what GDAL writes into a file and what
#' [get_projection()] returns, so it is here for comparing against those.
#'
#' @param crs A coordinate reference system, in any form GDAL reads.
#' @param format `"WKT2"`, or `"WKT2_2015"` or `"WKT2_2019"` for a particular
#'   edition, or `"WKT1"`.
#' @param multiline Whether to lay it out over several lines, which is how to
#'   read one rather than how to store it.
#' @return A WKT string.
#' @export
#' @examples
#' substr(crs_to_wkt("EPSG:4326"), 1, 30)
#' substr(crs_to_wkt("EPSG:4326", "WKT1"), 1, 30)
#'
#' cat(crs_to_wkt("EPSG:3857", multiline = TRUE))
crs_to_wkt <- function(crs, format = c("WKT2", "WKT2_2019", "WKT2_2015", "WKT1"),
                       multiline = FALSE) {
  format <- match.arg(format)
  GDAL7_crs_to_wkt(crs, format, isTRUE(multiline))
}

# ============================================================================
# Batched summary
# ============================================================================

#' Summarise a dataset in one call
#'
#' Everything `gdalinfo` reports that does not need a pass over the pixels,
#' fetched in a single call rather than one per property. Reached one accessor
#' at a time the same summary is seven round trips per band plus a handful for
#' the dataset, which over `/vsicurl/` is the difference between immediate and
#' sluggish.
#'
#' @param x A GDALDataset, or a DSN string to open and close again.
#' @return A list with `driver`, `driver_long`, `size`, `bands` (the count),
#'   `projection`, `geotransform`, `files`, `metadata`, and `band_info`, a data
#'   frame with one row per band.
#' @export
#' @examples
#' info <- gdal_info(system.file("extdata/test.tif", package = "GDAL7"))
#' info$size
#' info$band_info
gdal_info <- function(x) {
  if (is.character(x)) {
    ds <- gdal_open(x)
    on.exit(gdal_close(ds), add = TRUE)
  } else {
    ds <- x
  }

  info <- GDAL7_dataset_summary(ds@.ptr)
  info$band_info <- as.data.frame(info$band_info, stringsAsFactors = FALSE)
  info
}

